+func keybinds(ctx context.Context, cancel context.CancelFunc, dr *drawer) func(*terminalapi.Keyboard) {
+	return func(k *terminalapi.Keyboard) {
+		switch k.Key {
+		case keyboard.KeyCtrlC: // Quit
+			cancel()
+		case keyboard.KeyEnter: // Attack
+			attack(ctx, dr)
+		}
+	}
+}
